#!/usr/bin/env python3
"""Reopen B3 bytes, rederive scores, and apply the frozen stratified rule."""
from __future__ import annotations
import argparse,datetime as dt,hashlib,json,re,statistics,sys
from pathlib import Path
HERE=Path(__file__).resolve().parent;sys.path.insert(0,str(HERE.parent/"pilot_v2"))
from task_pack import family,schedule  # noqa: E402
from score import score  # noqa: E402
OPAQUE=re.compile(r"^attempt-[0-9a-f]{16}$")
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def req(x,m):
 if not x:raise ValueError(m)
def main():
 ap=argparse.ArgumentParser();ap.add_argument("--receipt",type=Path,required=True);ap.add_argument("--approval",type=Path,required=True);ap.add_argument("--rule",type=Path,required=True);ap.add_argument("--out",type=Path,required=True);a=ap.parse_args();r=json.loads(a.receipt.read_text());rule=json.loads(a.rule.read_text());req(r["approval_sha256"]==sha(a.approval),"APPROVAL_HASH");req(r["completed_episodes"]==r["planned_episodes"]==8,"COUNT");req(r["model"]=="anthropic/claude-opus-4-6","MODEL");req(r["code"]=={n:sha(HERE/n) for n in ("build_task.py","score.py","tools.js","run.py")},"CODE")
 expected=[f"{f}|{c}" for f,c in schedule()];req([e["episode_id"] for e in r["episodes"]]==expected,"ORDER");pairs={};validated=[]
 for e in r["episodes"]:
  wd=Path(e["workdir"]);req(OPAQUE.fullmatch(wd.name) is not None and e["condition"].lower() not in str(wd).lower(),"OPAQUE");req(sha(wd/"transcript.jsonl")==e["transcript_sha256"],"TRANSCRIPT");req(sha(wd/"record_access_log.json")==e["access_log_sha256"],"ACCESS");ars=json.loads((wd/"record_access_log.json").read_text());reads=sorted(set(str(x.get("record_id","")).upper() for x in ars if x.get("tool")=="read_record" and x.get("charged")));req(reads==e["model_reads"],"READS");alloc=json.loads((wd/"allocation.json").read_text())["allocated_record"]["id"];req(alloc==e["allocated_record"] and (wd/"allocation.json").stat().st_size==512,"ALLOCATION");vr=sorted(set(reads+[alloc]));req(vr==e["verification_records"] and len(vr)<=2,"BUDGET");payload=json.loads((wd/"decision.json").read_text());rescore=score(payload,e["truth"],family(e["family"])["critical_record"],2,vr);req(rescore==e["score"],"RESCORE");pairs.setdefault(e["family"],{})[e["condition"]]=e;validated.append(e["episode_id"])
 affected=set(rule["affected_families"]);unaffected=set(rule["unaffected_families"]);req(set(pairs)==affected|unaffected,"FAMILY_SET")
 def fc(e):return bool(e["score"].get("fully_correct"))
 awins=sum(fc(pairs[f]["C_TARGET"]) and not fc(pairs[f]["C_BASE"]) for f in affected);aloss=sum(fc(pairs[f]["C_BASE"]) and not fc(pairs[f]["C_TARGET"]) for f in affected);ustable=sum((not fc(pairs[f]["C_BASE"]) or fc(pairs[f]["C_TARGET"])) and not pairs[f]["C_TARGET"]["score"].get("overreaction") for f in unaffected);crit=sum(pairs[f]["C_TARGET"]["score"].get("critical_inspected") and not pairs[f]["C_BASE"]["score"].get("critical_inspected") for f in affected);alladm=all(e["score"].get("admissible") and not e["score"].get("budget_violation") for e in r["episodes"]);tt=sum(e["usage"]["total_tokens"] for e in r["episodes"] if e["condition"]=="C_TARGET");bt=sum(e["usage"]["total_tokens"] for e in r["episodes"] if e["condition"]=="C_BASE");ratio=tt/bt;passes=alladm and awins==2 and aloss==0 and ustable==2 and crit==2 and ratio<=1.2 and all(not pairs[f]["C_TARGET"]["score"].get("stale_consistent") for f in affected)
 summary={"affected_target_wins":awins,"affected_losses":aloss,"unaffected_no_harm":ustable,"critical_inspection_wins":crit,"all_admissible":alladm,"target_tokens":tt,"base_tokens":bt,"token_ratio":ratio,"target_fully_correct":sum(fc(e) for e in r["episodes"] if e["condition"]=="C_TARGET"),"base_fully_correct":sum(fc(e) for e in r["episodes"] if e["condition"]=="C_BASE"),"target_stale":sum(e["score"].get("stale_consistent",False) for e in r["episodes"] if e["condition"]=="C_TARGET"),"base_stale":sum(e["score"].get("stale_consistent",False) for e in r["episodes"] if e["condition"]=="C_BASE"),"decision":"PROMOTE_TO_C_PLANNING" if passes else "HOLD_OR_REJECT","C_authorized":False}
 out={"schema_version":"argo-b3-validation-analysis/v1","created_at":dt.datetime.now().astimezone().isoformat(timespec="seconds"),"source_receipt_sha256":sha(a.receipt),"approval_sha256":sha(a.approval),"rule_sha256":sha(a.rule),"validator_sha256":sha(Path(__file__)),"validation":{"passed":True,"episodes":len(validated),"transcripts_rederived":len(validated),"access_logs_rederived":len(validated),"scores_rederived":len(validated),"budget_and_order_verified":True},"frozen_rule_result":summary,"scope":"four-family development pilot; one rollout each; not confirmatory"};a.out.write_text(json.dumps(out,ensure_ascii=False,indent=2)+"\n");print(json.dumps(summary,indent=2))
if __name__=="__main__":main()
